#include <iostream>
using namespace std;

using ll = long long;

inline ll calc(ll n) {
    return n * (n - 1) / 2;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m;
    cin >> n >> m;

    ll q = n / m;
    ll r = n % m;

    ll minimum = r * calc(q + 1) + (m - r) * calc(q);
    ll maximum = calc(n - m + 1);

    cout << minimum << ' ' << maximum;
    return 0;
}

